INSERT INTO "vocab_areas" ("doc_id", "name", "definition", "found_definition", "pages") VALUES
('biodic_6th_kanagawa_h16', '丹沢全域', '丹沢全域と特定流域という2つの空間スケールで、生物種の目録調査及び生物群集の構造（構成種、分布など）を把握した。', 1, '[]'),
('biodic_6th_kanagawa_h16', '東丹沢モニタリングエリア（東丹沢MA）', '東丹沢と西丹沢において、自然条件が異なる2流域にモニタリングエリアを設置し、植生タイプごとの生物群集の構成種や分布など、種間関係や種と生息地との関係を解析するための詳細な生物生息情報を収集した。', 1, '[]'),
('biodic_6th_kanagawa_h16', '西丹沢モニタリングエリア（西丹沢MA）', '東丹沢と西丹沢において、自然条件が異なる2流域にモニタリングエリアを設置し...（東丹沢MAと同一記述内で対をなす区域）', 1, '[]'),
('biodic_6th_kanagawa_h16', '植生タイプ（スギ林・ヒノキ林・アカマツ林・フサザクラ等渓畔林・シデ等渓畔林・ケヤキ林・モミ林・ブナ林・崩壊地の9区分）', '丹沢山地東部に位置する札掛地区を調査地域として、9つの植生タイプの◯◯林分に方形枠を設置した（図1）。◯◯林分の内訳は、スギ林が4か所、ヒノキ林が2か所、アカマツ林が2か所、フサザクラ等渓畔林が2か所、シデ等渓畔林が2か所、ケヤキ林が2か所、モミ林が2か所、ブナ林が2か所、崩壊地が1か所である。', 1, '[]'),
('biodic_6th_kanagawa_h16', '自然林種／人工林種／ジェネラリスト／低頻度種（生育環境の選好性区分）', '植物種がどの植生タイプに偏って出現するか、すなわち種の生育環境の選好性を統計的検定により8タイプに区分した...人工林に偏って出現した種は人工林種、自然林に偏って出現した種は自然林種とした...出現頻度の合計が5以下である場合は低頻度種とした。有意差がみられなかった種はジェネラリストとした。', 1, '[]'),
('biodic_6th_kanagawa_h16', 'ブナ林種／モミ林種／渓畔林種／崩壊地性種／自然林ジェネラリスト（自然林種の内訳区分）', '次に自然林種を同様の手順で、崩壊地に偏って出現した種（崩壊地性種）と崩壊地以外の種、偏りに有意差がみられない種（自然林ジェネラリスト）に区分した。そして崩壊地以外の種を、同様の手順でブナ・モミ林に偏って出現する種〈ブナ・モミ林種〉渓畔林に偏って出現する種（渓畔林種） 偏りのみられない種（自然林ジェネラリスト）に区分し、最後にブナ・モミ林種を、ブナ林に偏って出現する種（ブナ林種）とモミ林に偏って出現する種（モミ林種） 偏りのみられない種（自然林ジェネラリスト）に区分した。', 1, '[]'),
('biodic_6th_kanagawa_h16', '希少性区分A〜E', '『神奈川県植物誌◯◯◯◯』を用いて種の分布地点数から希少性を5区分した。その区分は、分布地点数が◯◯以下、◯◯以上◯◯未満、◯◯以上◯◯◯未満、◯◯以上◯◯◯未満、◯◯◯以上である。（表3注：A：◯◯以下、B：◯◯以上◯◯未満、C：◯◯以上◯◯未満、D：◯◯以上◯◯◯未満、E：◯◯◯以上）', 1, '[]'),
('biodic_6th_kanagawa_h16', '高採食圧区／低採食圧区／採食圧除去区', '堂平地区は、◯◯◯◯年代からシカの採食影響の高まりにより、林床植生の衰退が見られる地域である...堂平地区は高密度状態が◯◯年以上継続していることから高採食圧区、菰釣山地区は低密度のため低採食圧区とした。また、堂平地区において設置後7年経過した柵内を採食圧除去区とした。', 1, '[]'),
('biodic_6th_kanagawa_h16', '衰退度ランク（0〜4）', '0：健全、枯枝は認められない／1：枯れた小枝が少しある／2：枯れた小枝がふえ、太い枝から小枝が出る／3：枯れた小枝の古いものは落ち、更に枯枝が増える／4：枯枝の太いものも落ち、着葉は小枝だけになる（図1 衰退度のランク、山家（◯◯◯◯）をもとに作成）', 1, '[]'),
('biodic_6th_kanagawa_h16', '自然林（区分）', NULL, 0, '[]'),
('biodic_6th_kanagawa_h16', '二次林', NULL, 0, '[]'),
