INSERT INTO "vocab_areas" ("doc_id", "name", "definition", "found_definition", "pages") VALUES
('tanzawa_shika_plan5', '保護管理区域', '県内33市町村のうち、シカの主要な生息分布域である丹沢山地を含む8市町村　相模原市（緑区のうち旧津久井町の区域）、秦野市、厚木市、伊勢原市、松田町、山北町、愛川町及び清川村', 1, '[1]'),
('tanzawa_shika_plan5', '定着防止区域', '(1)以外で、シカの生息や目撃情報等が得られている市町　相模原市（緑区のうち旧藤野町、旧相模湖町、旧城山町の区域）、平塚市、小田原市、南足柄市、大磯町、二宮町、中井町、大井町、開成町、箱根町、真鶴町及び湯河原町（※第3次計画中は「分布拡大防止区域」、第2次計画中は「監視区域」）', 1, '[2]'),
('tanzawa_shika_plan5', '自然植生回復エリア', '丹沢山地の主に高標高域（概ね800m以上）に位置し、主稜線部の丹沢大山国定公園特別保護地区を中心とするエリアである。丹沢山地の主稜線部にあって、丹沢大山国定公園の中核的地域として人為的な改変を避けて優れた自然環境が保全されている。このエリアでは、シカによる過度の採食圧によって林床植生の劣化が顕在化していることから、シカの生息密度を低減し、林床植生を早期に回復させることを目標に、主に県が主体となって管理捕獲を中心に管理事業を実施する', 1, '[10]'),
('tanzawa_shika_plan5', '生息環境管理エリア', 'スギやヒノキの人工林が広がる中標高域（概ね300〜800m）に位置し、丹沢大山国定公園及び県立丹沢大山自然公園の特別地域を中心とするエリアである。人工林や二次林において、水源の森林づくり事業等により、森林整備が行われている。このエリアをシカの主要な生息域として位置付け、林床植生の衰退が生じないレベルでシカを安定的に生息させることを目標として、主に県が主体となってシカ管理捕獲と森林整備を連携させた管理事業を実施する', 1, '[10]'),
('tanzawa_shika_plan5', '被害防除対策エリア', '主に山麓部（概ね300m以下）に位置し、保護管理区域のうち、自然植生回復エリア及び生息環境管理エリア以外のエリアである。農地及び市街地が広がり、人の経済活動が活発な地域である。このエリアでは、農地周辺でのシカの定着を解消し、農林業被害を軽減することを目標に、市町村等地域が主体となって被害防除対策と管理捕獲を中心に管理事業を実施する', 1, '[10]'),
('tanzawa_shika_plan5', '箱根山地', '箱根山地では、シカの定着が進んでおり、生息密度の増加により部分的な林床植生が衰退する懸念があるため、継続的かつこれまでよりも高い捕獲圧をかけていく必要がある。', 1, '[11, 17]'),
('tanzawa_shika_plan5', '小仏山地', '小仏山地では、隣接都県からシカの移入を受けやすい地理的環境にあるため、モニタリングによる生息状況等の把握を行い、相模原市へ情報提供していく。', 1, '[11, 18]'),
('tanzawa_shika_plan5', '丹沢山地', '丹沢山地は神奈川県の北西部に位置し、北西端に大室山、中核部に蛭ヶ岳・丹沢山、塔ノ岳、東端に大山などの峰があり、それらの峰から北東〜南西方向に延びる稜線と谷の繰り返し、並びに北西〜南東方向に延びる稜線とが組み合わさった複雑な地形をなしている。', 1, '[28]');
